// TOTP Generator Murni berbasis Web Crypto API
window.jsotp = window.jsotp || {};

window.jsotp.TOTP = class {
  constructor(secret) {
    this.secret = secret;
  }

  // Menghasilkan kode 6 digit berbasis waktu saat ini
  async generateCode() {
    const epoch = Math.floor(Date.now() / 1000);
    const timeStep = Math.floor(epoch / 30);
    
    // Konversi timeStep ke 8-byte buffer (Big Endian)
    const buffer = new ArrayBuffer(8);
    const view = new DataView(buffer);
    view.setUint32(4, timeStep, false);

    // Decode Secret Key dari Base32
    const keyBytes = Base32.decode(this.secret);

    // Import Key ke Web Crypto API
    const cryptoKey = await crypto.subtle.importKey(
      "raw",
      keyBytes,
      { name: "HMAC", hash: { name: "SHA-1" } },
      false,
      ["sign"]
    );

    // Hitung HMAC-SHA1
    const signature = await crypto.subtle.sign("HMAC", cryptoKey, buffer);
    const hmac = new Uint8Array(signature);

    // Dynamic Truncation
    const offset = hmac[hmac.length - 1] & 0x0f;
    const binary =
      ((hmac[offset] & 0x7f) << 24) |
      ((hmac[offset + 1] & 0xff) << 16) |
      ((hmac[offset + 2] & 0xff) << 8) |
      (hmac[offset + 3] & 0xff);

    const otp = binary % 1000000;
    return otp.toString().padStart(6, '0');
  }
};